export const meta = {
  name: 'greenfield-build',
  description: 'Detect/confirm empty target → load conventions as a constitution → decide architecture → scaffold repo + CI → build one vertical slice TDD → gates → acceptance → handoff docs',
  whenToUse: 'When starting a brand-new app/service/module where little or no code exists yet (the inverse of ship-feature). Pass { idea, stack:"<stack key from the stack manifests>", repos:{backend,frontend}, url, brief:"product-brief.md" }. With a brief from /product-brief, it is read as the constitution and the first backlog slice is the idea. It scaffolds (gate tooling + CI included) and ships ONE end-to-end vertical slice, then appends the next slices to backlog.md; use ship-feature for subsequent features.',
  phases: [
    { title: 'Detect', detail: 'Confirm the target is empty/greenfield; capture intended stack', model: 'sonnet' },
    { title: 'Constitution', detail: 'Load the product brief, conventions + skills as governing architecture constraints', model: 'opus' },
    { title: 'Architecture', detail: 'Decide stack, layout, data model, first slice; verify vs constitution', model: 'opus' },
    { title: 'Scaffold', detail: 'Create repo skeleton with working gate tooling (+ contract-sync for split repos), then CI; commit the scaffold checkpoint', model: 'sonnet' },
    { title: 'Slice', detail: 'Build one vertical slice end-to-end, TDD-first', model: 'sonnet' },
    { title: 'Gates', detail: 'Assert the scaffold builds and the slice passes the tooling', model: 'sonnet' },
    { title: 'Acceptance', detail: 'Trace the first-slice journey end-to-end', model: 'opus' },
    { title: 'Handoff', detail: 'getting-started.md, architecture.md (ADR), manual-test.md', model: 'sonnet' },
    { title: 'Report', detail: 'Append next slices to backlog.md; what was decided, scaffolded, slice status', model: 'opus' },
  ],
}

