// --- Detect: confirm the target is genuinely greenfield -----------------
phase('Detect')
const detection = await detectStacks(
  `Determine the target directories for a NEW project and whether they are safe to scaffold into. Use Bash to probe — do not assume.
Idea: ${idea}
${stackHint ? `Intended stack: ${stackHint}` : 'Stack not specified — infer the most appropriate from the idea.'}
${repoHints ? `Target repo roots: ${JSON.stringify(repoHints)}` : 'No target roots given — use the current directory (and a directory inside it for a split frontend if appropriate).'}

Recognized stacks — pick the matching key for each target and record its gateCommands + conventions:
${stackCatalog()}

For each intended target, report: role, path, the intended stack, empty (no source files), and hasTrackedFiles (\`git -C <path> ls-files | head -1\` returns anything). Set greenfield=true only if every target is empty OR has no tracked source files. If any target already contains a real tracked codebase, add a blocker (scaffolding would clobber existing work) and set greenfield=false. Decide single vs split repos from the idea and stack.

${stackDiscoveryPrompt()}`,
  { phase: 'Detect', schema: TARGET_SCHEMA, agentType: 'code-explorer', ...MODELS.detect }
)
const target = detection.project
const { list: targets, stackOverlay, untrusted: untrustedManifests } = resolveDetect(target, {
  failure: detection.failure,
  roots: repoHints,
  listKey: 'targets',
  fallback: { role: 'fullstack', path: '.', stack: stackHint || 'other', empty: true, hasTrackedFiles: false },
})
// Report prompts quote these validated fields of a target, never the Detect object itself.
function targetSummary(t) {
  return { role: t.role, stack: t.stack, path: t.path, empty: t.empty === true, hasTrackedFiles: t.hasTrackedFiles === true }
}
// A scaffold's gate check as report prompts quote it: names and details that pass the safe-text pattern only.
function scaffoldGateCheck(s) {
  return (Array.isArray(s.gateCheck) ? s.gateCheck : []).filter((g) => g && typeof g === 'object').map((g) => ({
    name: safeTexts([g.name], 'Scaffold gate name')[0] || '?',
    ran: g.ran === true,
    applicable: g.applicable !== false,
    details: g.details ? safeTexts([g.details], 'Scaffold gate details')[0] || '(details dropped)' : '',
  }))
}
const crossRepo = !!(target && target.crossRepo) || targets.length > 1
const blockers = safeTexts(target && target.blockers, 'Detect blockers')
const notGreenfield = (target && target.greenfield === false) || targets.some((t) => t.hasTrackedFiles)
log(`Detect: ${targets.map((t) => `${t.role}:${t.stack}@${t.path}`).join(', ')}${crossRepo ? ' (split)' : ''}; greenfield=${!notGreenfield}`)

if (notGreenfield && !force) {
  blockers.forEach((b) => log(`⛔ ${b}`))
  phase('Report')
  const blocked = await runAgent(
    `Write a short markdown report: greenfield-build was asked to scaffold into a target that already contains a tracked codebase, so it STOPPED to avoid clobbering work. State the idea, the targets and why each is unsafe, and the options (point at an empty dir, or re-run with { force:true } only if intentional, or use ship-feature to add to the existing codebase). Recommendation: BLOCKED.
Idea: ${idea}
Targets: ${JSON.stringify(targets.map(targetSummary))}
Blockers: ${JSON.stringify(blockers)}`,
    { phase: 'Report', ...MODELS.report }
  )
  return { idea, greenfield: false, recommendation: 'BLOCKED', blockers, report: blocked }
}

// A target whose stack manifest is not trusted runs nothing from it: no scaffold, CI, slice or gates.
const untrustedTargets = targets.filter((t) => isUntrustedStack(t.stack))
if (untrustedTargets.length) {
  const blocking = blockingUntrusted(untrustedManifests, targets)
  const trustNext = untrustedNext('greenfield-build', blocking)
  const notRun = untrustedTargets.map((t) => ({ repo: t.path, gates: gatePlanFor(t).fixed, allPassed: false }))
  log(`Untrusted stack manifest for ${untrustedTargets.map((t) => `${t.stack}@${t.path}`).join(', ')}: nothing scaffolded`)
  phase('Report')
  const blocked = await runAgent(
    `Write a short markdown report: greenfield-build STOPPED before scaffolding because the stack manifest for ${untrustedTargets.map((t) => `${t.stack} (${t.path})`).join(', ')} is not trusted, so none of its commands (scaffold, gates, CI, e2e, contract-sync) may run. Nothing was created. State the idea, the targets, the untrusted manifest sources and their sha256, and that /stack-trust shows every command the manifest declares before approving it. Add a "Stack overlay" line: ${stackOverlayLine(stackOverlay, untrustedManifests)}. Recommendation: BLOCKED. End with exactly "${trustNext}".
Idea: ${idea}
Targets: ${JSON.stringify(targets.map((t) => ({ role: t.role, stack: t.stack, path: t.path })))}
Untrusted: ${JSON.stringify(blocking)}
Gates: ${JSON.stringify(notRun)}`,
    { phase: 'Report', ...MODELS.report }
  )
  return {
    idea,
    greenfield: true,
    stacks: targets.map((t) => ({ role: t.role, stack: t.stack, path: t.path })),
    scaffolded: false,
    gatesPassed: false,
    gates: notRun,
    recommendation: 'BLOCKED',
    stackOverlay: { ...stackOverlay, untrusted: untrustedManifests },
    next: trustNext,
    report: blocked,
  }
}

const frontendTarget = targets.find(isFrontendRepo)
const primaryTarget = targets.find((t) => t.role === 'backend' || t.role === 'fullstack') || targets[0]
const devUrl = resolveDevUrl(devUrlHint, targets)
// Skills the manifests list for the chosen stacks, one clause per stack.
const constitutionSkills = targets.map((t) => `for ${t.stack} — ${skillNamesFor(t.stack).join(', ') || 'infer from the repo'}`).join('; ')
function agentForStack(stack) {
  return STACK_AGENT[stack] || STACK_AGENT[(primaryTarget && primaryTarget.stack)] || 'general-purpose'
}
function targetForStack(stack) {
  return targets.find((t) => t.stack === stack) || primaryTarget
}

// --- Constitution: governing principles before any architecture ---------
phase('Constitution')
const constitution = await runAgent(
  `Establish the non-negotiable principles this new project's architecture must satisfy, BEFORE deciding the architecture. Treat the framework's conventions and skills as a constitution (the way spec-driven development front-loads principles).
Idea: ${idea}
Intended stacks: ${JSON.stringify(targets.map((t) => t.stack))}

1. ${briefPath ? `Read the product brief at "${briefPath}" first — it is the constitution's source: its MVP scope, non-goals, numbered business rules (BR-nn, keep the ids), constraints, and the backlog.md next to it.` : 'If a product-brief.md exists in the current folder or its parent, read it first — its MVP scope, non-goals, business rules (BR-nn) and constraints govern everything below.'}
   Then read the project/global CLAUDE.md and any docs/context/*.md (the Golden Triangle) if present.
2. Consult the relevant framework skills for the chosen stack(s): ${constitutionSkills}; plus architecture-patterns and error-handling-patterns. Name the ones you used.
3. Return the principles (concrete, testable architectural constraints — e.g. "request handlers stay thin; business logic lives in its own layer", "typed data objects at layer boundaries", "every schema change is documented before it is applied"), the brief's business rules that the first slice must enforce (with their BR ids), and the conventions the scaffold + slice must follow.`,
  { phase: 'Constitution', schema: CONSTITUTION_SCHEMA, agentType: 'code-explorer', ...MODELS.constitution }
)
const principles = (constitution && constitution.principles) || []
log(`Constitution: ${principles.length} principle(s), skills: ${(constitution && constitution.skillsConsulted || []).join(', ') || 'none'}`)

// --- Architecture: decide, then adversarially verify vs constitution ----
phase('Architecture')
const architecture = await runAgent(
  `Decide the architecture for this new project, grounded in the constitution. Be concrete and minimal — enough to scaffold and ship one vertical slice, not a cathedral.
Idea: ${idea}
Targets: ${JSON.stringify(targets.map((t) => ({ role: t.role, stack: t.stack, path: t.path })))}
Principles (must satisfy): ${JSON.stringify(principles)}
Conventions: ${JSON.stringify((constitution && constitution.conventions) || [])}

You run inside a background workflow and cannot reach the user: do not ask. Where the idea or principles leave something open, choose the simplest option that satisfies the principles and record it in decisions as an assumption (rationale + alternativesConsidered).
Decide: stacks confirmed, repoLayout (single or split), the layers (e.g. entry point → service → data access → db; or page → component → API client), a minimal dataModelSketch, and the FIRST vertical slice — the smallest end-to-end feature that proves the stack works (title, the entryPoint a user hits, the expectedEndState). Record decisions with rationale + alternativesConsidered, and which principles each satisfies (principlesSatisfied).`,
  { phase: 'Architecture', schema: ARCHITECTURE_SCHEMA, agentType: ARCHITECT_AGENT, ...MODELS.architecture }
)
if (!architecture || !architecture.firstSlice) {
  log('Architecture phase produced no first slice — cannot proceed.')
  return { idea, greenfield: true, error: 'no architecture decided', constitution }
}
// Adversarially verify the architecture honors the constitution before building.
const archVotes = (await parallel(
  ['principle-adherence', 'simplicity', 'stack-fit'].map((lens) => () =>
    runAgent(
      `An architecture proposal for a new project. Idea: ${idea}.
Decisions: ${JSON.stringify(architecture.decisions)}. Layout: ${architecture.repoLayout}. First slice: ${JSON.stringify(architecture.firstSlice)}.
Must satisfy these principles: ${JSON.stringify(principles)}.
Judge through the ${lens} lens. Try to REFUTE: does it violate a principle, over-engineer, or mismatch the stack? default real=false (i.e. NOT sound) if you find a real problem; real=true only if it genuinely holds up.`,
      { phase: 'Architecture', label: `verify:arch`, schema: VERDICT_SCHEMA, ...MODELS.verify }
    )
  )
)).filter(Boolean)
const archYes = archVotes.filter((v) => v.real).length
const archSound = archVotes.length > 0 && archYes >= Math.ceil(archVotes.length / 2)
log(`Architecture: slice "${architecture.firstSlice.title}" — ${archSound ? 'sound' : 'CONCERNS'} (${archYes}/${archVotes.length})`)
const archConcerns = archVotes.filter((v) => !v.real).map((v) => v.reason)

// --- Scaffold: create skeleton + CI; commit the checkpoint --------------
phase('Scaffold')
// The scaffold installs the stack's own test tooling, so a fallback gate that applies
// only when no test tooling exists (scaffoldSkipGates) never applies.
function registryGatesFor(t) {
  const gates = scaffoldGatesFor(t.stack)
  return gates.length ? gates.map((g) => `- ${g.name}: ${g.command}`).join('\n') : '- (the stack\'s own lint + test tooling)'
}
const contractBackend = crossRepo ? targets.find((x) => routeListCommandFor(x.stack)) : undefined
const splitStacks = !!contractBackend && targets.some((x) => isContractConsumer(x.stack))
// A scaffolded target as the gates see it: the scaffold's report only selects among the allowlisted commands
// (gateCommandsFor); without a report, the commands Detect found for the target stand.
// The package manager is kept only when the stack's manifest declares it (declaredPackageManager).
const scaffoldedTarget = (t, reported, packageManager) => ({
  ...t,
  gateCommands: Array.isArray(reported) && reported.length ? reported : t.gateCommands || [],
  packageManager: declaredPackageManager(t.stack, packageManager, t.path) || t.packageManager,
})
const scaffoldPrompt = (t) =>
  `Scaffold the ${t.role} repo (${t.stack}) at "${t.path}" for this new project. Create the framework skeleton, the project structure per the architecture, and working quality-gate tooling. Mechanical work — follow conventions exactly, write no business logic yet. CI is added in a separate step; do not write CI files.
Idea: ${idea}
Architecture: ${JSON.stringify({ layout: architecture.repoLayout, layers: architecture.layers, dataModel: architecture.dataModelSketch })}
Decisions to preserve: ${JSON.stringify(architecture.decisions || [])}
Conventions: ${JSON.stringify((constitution && constitution.conventions) || [])}

1. Initialize the stack skeleton (${scaffoldFor(t.stack).command ? `the \`${scaffoldFor(t.stack).command}\` layout` : 'the stack\'s standard skeleton'}) under "${t.path}". If the dir is non-empty but untracked, integrate without deleting existing files.
2. Add the layer directories the architecture calls for and a CLAUDE.md + .mcp.json if absent.
3. Install and configure the gate tools so every gate below runs on the empty skeleton:
${registryGatesFor(t)}
${scaffoldFor(t.stack).tooling.map((x) => `   - ${x}`).join('\n')}${scaffoldFor(t.stack).tooling.length ? `\n   First-slice entry point: ${architecture.firstSlice.entryPoint}.` : ''}${packageManagerLine(t.stack) ? `\n   ${packageManagerLine(t.stack)}` : ''}${splitStacks && isContractConsumer(t.stack) ? `
4. Split repos: wire contract-sync. Copy the backend add-on's contract-sync checker (contract-sync.mjs from ${contractTemplateFor(contractBackend.stack) || 'the backend add-on\'s contract-sync template'}) to scripts/contract-sync.mjs, point its CONFIG at the backend's \`${routeListCommandFor(contractBackend.stack)}\` (backend repo: ${contractBackend.path}) and at this repo's API endpoint registry, register it as a "contract-sync" script in the repo's task runner, and set contractSync=true.` : ''}
${splitStacks && isContractConsumer(t.stack) ? '5' : '4'}. Run every applicable gate once. Report each gate listed in step 3 in gateCheck (name, ran, applicable, details): applicable=false only for a gate this scaffold deliberately does not install (an e2e gate when the first slice has no UI journey), with the reason in details; ran=true only when the tool executed (pass or a real failure in code); ran=false when an applicable tool is missing or cannot start. Never report a gate you did not run.
${splitStacks && isContractConsumer(t.stack) ? '6' : '5'}. \`git init\` if needed, then commit the scaffold as the first checkpoint with a Conventional Commits subject such as "chore: scaffold <app>" (no AI-marker comments).
Return the created paths, packageManager${packageManagersFor(t.stack).length ? ' (the one the lockfile names)' : ' (omit it: the stack declares no package managers)'}, the real gateCommands (tagged with repo="${t.path}"; ${gateReportRule(t.stack)}), gateCheck, and committed=true.`

const ciPrompt = (t, s) =>
  `Add the CI verification chosen by the architecture for the ${t.role} repo (${t.stack}) at "${t.path}" — cd there. The skeleton and gate tooling already exist and were committed.
Architecture decisions (binding): ${JSON.stringify(architecture.decisions || [])}
First-slice expected end state: ${architecture.firstSlice.expectedEndState}
Gate commands to run in CI, in this order: ${JSON.stringify(gatePlanFor(scaffoldedTarget(t, s && s.gateCommands, s && s.packageManager)).run.map((g) => g.command))}
Package manager: ${(s && declaredPackageManager(t.stack, s.packageManager, t.path)) || 'from the lockfile'}.
For local-only CI, implement the agreed checked-in runner (for example ci.sh), fail on the first failing command, and do not add a hosted workflow. Otherwise use the architecture's chosen provider; use .github/workflows/ci.yml following the ci-cd skill only when GitHub Actions is selected or no provider/local-only choice was made. For a hosted workflow use one job per stack, dependency caching keyed on the lockfile when dependencies exist, and every gate above as its own step. Configure ${ciFor(t.stack).services.length ? `the declared services (${ciFor(t.stack).services.join('; ')}) and ` : ''}${ciFor(t.stack).setup.length ? `setup steps (${ciFor(t.stack).setup.join('; ')}) and ` : ''}the gate tooling for the chosen environment. ${s && s.contractSync ? 'Add a contract-sync step that reads the backend route list through the chosen local or hosted arrangement (see the contract-sync README).' : ''}
Never weaken a gate to get green (no continue-on-error, no skipped tests). Run the local runner when one is required; writing a file alone is not execution evidence. Commit the CI files as a second checkpoint. Return configured, files, the job names (empty for a local runner), and committed.`

async function scaffoldTarget(t) {
  const result = await runAgent(scaffoldPrompt(t), { phase: 'Scaffold', label: `scaffold:${t.role}`, schema: SCAFFOLD_SCHEMA, agentType: agentForStack(t.stack), ...MODELS.scaffold })
  return result ? { ...result, target: t } : null
}
const scaffolds = (crossRepo
  ? await parallel(targets.map((t) => () => scaffoldTarget(t)))
  : [await scaffoldTarget(primaryTarget)]).filter(Boolean)

// CI is its own step on the devops specialist, after the skeleton and tooling exist.
const ciResults = (await parallel(scaffolds.map((s) => () =>
  runAgent(ciPrompt(s.target, s), { phase: 'Scaffold', label: `ci:${s.target.role}`, schema: CI_SCHEMA, agentType: CI_AGENT, ...MODELS.ci })
))).filter(Boolean)

const gateCommandsByRepo = {}
const packageManagerByRepo = Object.fromEntries(scaffolds.map((s) => [s.target.path, declaredPackageManager(s.target.stack, s.packageManager, s.target.path)]).filter(([, pm]) => pm))
scaffolds.forEach((s) => (s.gateCommands || []).forEach((g) => {
  const key = g && targets.some((t) => t.path === g.repo) ? g.repo : s.target.path
  ;(gateCommandsByRepo[key] = gateCommandsByRepo[key] || []).push({ name: g.name, command: g.command, evidence: g.evidence, script: g.script })
}))
const scaffolded = scaffolds.some((s) => (s.created || []).length)
const ciConfigured = ciResults.some((c) => c.configured)
const unrunnableGates = scaffolds.flatMap((s) => scaffoldGateCheck(s).filter((g) => g.applicable && !g.ran).map((g) => `${g.name}${g.details ? ` (${g.details})` : ''}`))
log(`Scaffold: ${scaffolds.reduce((n, s) => n + (s.created || []).length, 0)} path(s) created, CI ${ciConfigured ? 'configured' : 'not configured'}${unrunnableGates.length ? `; gates that cannot run: ${unrunnableGates.join(', ')}` : ''}`)

// A gate that cannot run on the fresh skeleton would make every later "green" meaningless.
if (scaffolded && unrunnableGates.length) {
  phase('Report')
  const blocked = await runAgent(
    `Write a short markdown report: greenfield-build scaffolded the project but STOPPED before building the first slice because these quality gates cannot run: ${unrunnableGates.join('; ')}. For each, say what is missing (package, config file, environment) and the exact command to fix it. Recommendation: FIX-FIRST. Do NOT recommend re-running greenfield-build: the scaffold and architecture are committed, and a re-run would decide the architecture again and scaffold over the skeleton. Instead: fix the tooling, run the gates once to confirm, then build the first slice as a normal feature on the existing skeleton — \`Workflow({ name: "ship-feature", args: { feature: "<first slice: title, entry point, expected end state>", repos: <the targets> } })\`, or /sdd with the same description (it routes as a feature now that code exists). Include the decided architecture (layout, layers, data model, decisions) and the first slice so that run builds against them.
Idea: ${idea}
Architecture: ${JSON.stringify({ layout: architecture.repoLayout, layers: architecture.layers, dataModel: architecture.dataModelSketch, decisions: architecture.decisions })}
First slice: ${JSON.stringify(architecture.firstSlice)}
Scaffold: ${JSON.stringify(scaffolds.map((s) => ({ created: (s.created || []).length, gateCheck: scaffoldGateCheck(s) })))}`,
    { phase: 'Report', ...MODELS.report }
  )
  const sliceFeature = `${architecture.firstSlice.title}: entry point ${architecture.firstSlice.entryPoint}; done when ${architecture.firstSlice.expectedEndState}`
  return {
    idea,
    greenfield: true,
    scaffolded,
    recommendation: 'FIX-FIRST',
    unrunnableGates,
    architecture,
    firstSlice: architecture.firstSlice,
    next: [
      'Fix the tooling listed in the report and re-run the gates',
      `Workflow({ name: "ship-feature", args: { feature: ${JSON.stringify(sliceFeature)}, repos: ${JSON.stringify(Object.fromEntries(targets.map((t) => [t.role, t.path])))} } })`,
    ],
    report: blocked,
  }
}

// --- Slice: one vertical feature end-to-end, TDD-first ------------------
phase('Slice')
const sliceTouches = (architecture.firstSlice.touchesRepos && architecture.firstSlice.touchesRepos.length)
  ? architecture.firstSlice.touchesRepos
  : targets.map((t) => t.path)
const sliceRepos = targets.filter((t) => sliceTouches.includes(t.path))
const sliceReposOrdered = [
  ...sliceRepos.filter((t) => t.role !== 'frontend'),
  ...sliceRepos.filter((t) => t.role === 'frontend'),
]
const sliceBuilt = []
for (const t of (sliceReposOrdered.length ? sliceReposOrdered : [primaryTarget])) {
  if (budget.total && budget.remaining() < 80_000) {
    log(`Budget low (${Math.round(budget.remaining() / 1000)}k left) — stopping slice build.`)
    break
  }
  const prior = sliceBuilt.length ? `Already built: ${sliceBuilt.map((b) => b.summary).join('; ')}.` : 'This is the first part of the slice.'
  const part = await runAgent(
    `Build the ${t.role} part of the first vertical slice end-to-end using TDD (failing test first, then make it pass). Work in "${t.path}" (${t.stack}) — cd there.
Slice: ${architecture.firstSlice.title}
Entry point: ${architecture.firstSlice.entryPoint}
Expected end state: ${architecture.firstSlice.expectedEndState}
Layers: ${JSON.stringify(architecture.layers)}
Data model: ${JSON.stringify(architecture.dataModelSketch)}
Conventions/principles: ${JSON.stringify(principles)}
Architecture decisions (binding, including validation and error behavior): ${JSON.stringify(architecture.decisions || [])}
${prior}

Implement just enough to make the slice work end-to-end for this repo's part (e.g. backend: migration + model + service + controller + route + test; frontend: page + component + API call + test). Cover the applicable architecture decisions with regression tests, including rejected inputs and error paths. Do not silently substitute a broader contract or defer a first-slice requirement to the backlog. No AI-marker/changelog comments; match the scaffold's style. Return changed files (repo-relative) and completed=true only with passing tests and the applicable decisions implemented.`,
    { label: `slice:${t.role}`, phase: 'Slice', schema: BUILD_SCHEMA, agentType: agentForStack(t.stack), ...MODELS.slice }
  )
  if (part && part.completed !== false) sliceBuilt.push({ repo: t.path, ...part })
}
const sliceChanged = Array.from(new Set(sliceBuilt.flatMap((b) => b.changedFiles || [])))
const sliceComplete = sliceBuilt.length === (sliceReposOrdered.length || 1)
log(`Slice: ${sliceBuilt.length}/${sliceReposOrdered.length || 1} part(s) built${sliceComplete ? '' : ' (incomplete)'}`)

// --- Gates --------------------------------------------------------------
phase('Gates')
// runRepoGates passes the target with gateCommands set to its gate plan (plan.run).
function gateInstructionsFor(t) {
  const cmds = (t.gateCommands || []).map((g) => `- ${g.name}: ${g.command}`).join('\n')
  return `Run the quality gates for the ${t.role} repo (${t.stack}) at "${t.path}". cd there.
Gates (run each; tool genuinely absent => "skip"; tool present but cannot run => "unreachable", NEVER "pass"):
${cmds || noGatesLine(t, 'run the stack lint + test tooling that the scaffold configured')}
- Build check: confirm the scaffold itself builds/boots (e.g. the app starts, the test suite collects).
- Debug scan: grep for stray ${debugScanFor(t.stack)} outside tests -> fail if found.
Report each gate pass/fail/skip/unreachable with output in details; allPassed=true only if every gate is pass or skip; repo="${t.path}". Do not fix here.`
}
async function runGates() {
  const list = sliceReposOrdered.length ? sliceReposOrdered : targets
  const results = (await parallel(list.map((t) => () => runRepoGates(scaffoldedTarget(t, gateCommandsByRepo[t.path], packageManagerByRepo[t.path]), gateInstructionsFor, { label: `gates:${t.role}`, phase: 'Gates', schema: GATES_SCHEMA, ...MODELS.gatesFix })))).filter(Boolean)
  const allGates = results.flatMap((g) => (g.gates || []).map((x) => ({ ...x, repo: g.repo })))
  return { results, allGates, allPassed: results.length > 0 && results.every((g) => g.allPassed) }
}
let gates = await runGates()
let fixRounds = 0
while (!gates.allPassed && fixRounds < 3) {
  const failing = gates.allGates.filter(isFixableGate)
  if (!failing.length) { log('Gates not all green but nothing actionable — stopping.'); break }
  if (budget.total && budget.remaining() < 60_000) { log(`Budget low — stopping gate fixes.`); break }
  fixRounds++
  log(`Gates round ${fixRounds}: fixing ${failing.length} failing gate(s)`)
  const list = (sliceReposOrdered.length ? sliceReposOrdered : targets)
  await parallel(
    list.filter((t) => failing.some((f) => !f.repo || f.repo === t.path)).map((t) => () =>
      runAgent(
        `Quality gates are failing in the ${t.role} repo (${t.stack}) at "${t.path}". cd there. Fix the underlying code/config (not by suppressing errors or weakening tests).
Failures:
${failing.filter((f) => !f.repo || f.repo === t.path).map((g) => `- ${g.name}: ${g.details || ''}`).join('\n')}`,
        { label: `gates:fix${fixRounds}:${t.role}`, phase: 'Gates', agentType: agentForStack(t.stack), ...MODELS.gatesFix }
      )
    )
  )
  gates = await runGates()
}

// --- Acceptance: the first-slice journey resolves end-to-end ------------
phase('Acceptance')
let acceptance = null
if (!sliceBuilt.length) {
  log('Acceptance: skipped — no slice was built.')
} else {
  acceptance = await runAgent(
    `Verify the first vertical slice works end-to-end against the scaffolded code as it stands. Do NOT trust passing unit tests — re-walk the real journey.
Slice: ${architecture.firstSlice.title}
Entry point: ${architecture.firstSlice.entryPoint}
Expected end state: ${architecture.firstSlice.expectedEndState}
Architecture decisions: ${JSON.stringify((architecture.decisions || []).map((decision, decisionIndex) => ({ decisionIndex, ...decision })))}
Constitution principles: ${JSON.stringify(principles)}
Targets: ${JSON.stringify(targets.map((t) => ({ role: t.role, stack: t.stack, path: t.path })))}
Changed files: ${sliceChanged.join(', ')}

From the entry point, follow every hop to the expected end state (boot the app / run the route / load the page as needed). Record step/expected/actual/ok, including forbidden inputs and error behavior. A redirect or link whose target does not resolve is ok=false (brokenLinks). Return exactly one architectureChecks entry for EVERY listed decisionIndex, with ok and concrete evidence from commands or file inspection. Check the built code, not merely whether the plan sounds reasonable. An unmet, deferred, or unverified decision is ok=false; do not rewrite the architecture to match an accidental implementation. resolved=true ONLY if all journey steps and architecture checks pass with no broken hop.`,
    { phase: 'Acceptance', schema: ACCEPTANCE_SCHEMA, ...MODELS.acceptance }
  )
}
// A worker's overall boolean cannot overrule failed or missing evidence.
const architectureChecks = (acceptance && acceptance.architectureChecks) || []
const architectureImplemented = !!acceptance && architectureChecks.length === (architecture.decisions || []).length && (architecture.decisions || []).every((_, index) => {
  const matching = architectureChecks.filter((check) => check.decisionIndex === index)
  return matching.length === 1 && matching[0].ok === true && typeof matching[0].evidence === 'string' && matching[0].evidence.trim().length > 0
})
const acceptanceResolved = !!(acceptance && acceptance.resolved === true && acceptance.steps && acceptance.steps.length && acceptance.steps.every((step) => step.ok === true) && !(acceptance.brokenLinks || []).length && architectureImplemented)
if (acceptance) log(`Acceptance: ${acceptanceResolved ? 'RESOLVED' : 'NOT resolved'}${(acceptance.brokenLinks || []).length ? ` — broken: ${acceptance.brokenLinks.join(', ')}` : ''}`)

// --- Handoff: getting-started + architecture ADR + manual test ----------
phase('Handoff')
let handoff = null
if (!scaffolded) {
  log('Handoff: skipped — nothing scaffolded.')
} else {
  handoff = await runAgent(
    `Write the handoff docs for this new project so a human can run, understand, and verify it. File I/O + prose only. Lowercase filenames, no AI-marker/changelog comments.
Idea: ${idea}
Architecture: ${JSON.stringify(architecture)}
Constitution principles: ${JSON.stringify(principles)}
Slice built: ${JSON.stringify(sliceBuilt.map((b) => ({ repo: b.repo, summary: b.summary })))}
Acceptance: ${JSON.stringify(acceptance && { resolved: acceptanceResolved, steps: acceptance.steps, architectureChecks })}
App URL: ${devUrl}

Write (in the primary repo "${primaryTarget.path}", or a docs/ dir):
1. getting-started.md — exact install/build/run/test commands for each repo.
2. architecture.md — the decided design + rationale + alternatives (a lightweight ADR).
3. manual-test.md — copy-paste steps to verify the first slice by hand (action → expected), covering the slice's happy path.
Return the files written and the run commands.`,
    { phase: 'Handoff', schema: HANDOFF_SCHEMA, agentType: 'general-purpose', ...MODELS.handoff }
  )
  if (handoff) log(`Handoff: ${(handoff.files || []).length} doc(s) written`)
}

// --- Report -------------------------------------------------------------
phase('Report')
const blockingManifests = blockingUntrusted(untrustedManifests, targets)
const shippable = scaffolded && sliceComplete && gates.allPassed && acceptanceResolved && archSound && !blockingManifests.length
const recommendation = shippable ? 'SHIP-SLICE' : blockingManifests.length ? 'BLOCKED' : 'FIX-FIRST'
const trustNext = untrustedNext('greenfield-build', blockingManifests)
// The next slices go into backlog.md (product-brief's format), not only into prose,
// so /spec-board shows them and /sdd can start each one.
const backlogDir = briefPath ? (briefPath.includes('/') ? briefPath.slice(0, briefPath.lastIndexOf('/')) : '.') : (crossRepo ? '.' : primaryTarget.path)
const backlog = await runAgent(
  `Update the product backlog at "${backlogDir}/backlog.md" (create it if missing). Planning docs only — touch no code.
Format (product-brief's backlog.md): frontmatter (product, brief), a "Build order:" line, a "## Slices" section with one "### SL-nn · <title>" heading per slice, each followed by "- **Field:** value" lines in this order: Outcome, Entry point, Size (XS/S/M/L), BRs, Depends on, Blocked by, Status, Spec, Source, Run. New file: start the ids at SL-01 for the slice just built.
1. The slice just built: "${architecture.firstSlice.title}" (entry point ${architecture.firstSlice.entryPoint}). ${shippable
    ? 'If it is already in the file, set its Status to shipped and Spec to greenfield-build; otherwise add it that way.'
    : 'It is NOT shippable yet. If it is already in the file, set its Status to approved and leave Spec as — (an em dash); otherwise add it that way. Do not write greenfield-build into Spec: a Spec value takes the slice off the /spec-board Backlog column, and this unfinished slice must stay visible there until it ships.'}
2. Add the next slices this architecture implies (two to five, smallest useful first, each one user-visible outcome through every layer), unless an equivalent slice is already listed. Insert them at the END OF THE "## Slices" SECTION: after its last "### SL-nn" slice and before the next "## " heading (for example "## Intake log"), never at the end of the file — spec-board stops reading slices at the next level-2 heading, so a slice below it is silently dropped. Continue the SL numbering, Status: proposed, Spec: —, Source: greenfield-build, cite the brief's BR ids when there is a brief, and end each with a Run line: \`/sdd "SL-nn: <outcome> (BR ids). Rules in product-brief.md."\`.
3. Never reorder or rewrite existing approved slices; only add. Update the Build order line to include the new ids.
Architecture: ${JSON.stringify({ layers: architecture.layers, dataModel: architecture.dataModelSketch, decisions: architecture.decisions })}
Constitution principles: ${JSON.stringify(principles)}
Brief: ${briefPath || '(none — no BR ids to cite)'}
Return the path, created, the id marked shipped, and the appended ids.`,
  { phase: 'Report', label: 'backlog', schema: BACKLOG_SCHEMA, agentType: WRITER_AGENT, ...MODELS.handoff }
)
if (backlog) log(`Backlog: ${backlog.path}${backlog.created ? ' (created)' : ''} — appended ${(backlog.appended || []).join(', ') || 'nothing'}`)
const report = await runAgent(
  `Write a concise markdown report for this greenfield build. Sections: Summary, Idea, Stacks & repo layout, Constitution (key principles), Architecture decisions (with rationale + any verify concerns: ${JSON.stringify(archConcerns)}), Scaffold (what was created + CI), First slice (title + status), Quality gates per repo, Acceptance (does the first slice work end-to-end?), Handoff docs written, Recommendation (SHIP-SLICE / FIX-FIRST / BLOCKED — only SHIP-SLICE if scaffold + slice complete, gates pass, acceptance resolved, and the architecture is sound${trustNext ? `; an untrusted stack manifest means its gates did not run, so the recommendation is BLOCKED and the Next line is exactly "${trustNext}"` : ''}), and Next slices: the ids appended to backlog.md (with its path) and the Run line of the first one, which starts the next slice through /sdd.
Idea: ${idea}
Targets: ${JSON.stringify(targets.map(targetSummary))}
Computed recommendation: ${recommendation}. Do not claim a stronger outcome. Explicitly disclose any contrary evidence.
Stack overlay: ${JSON.stringify({ ...stackOverlay, untrusted: untrustedManifests })}
Architecture: ${JSON.stringify(architecture)} (plan sound=${archSound}; implemented=${architectureImplemented})
Scaffold: ${JSON.stringify(scaffolds.map((s) => ({ created: (s.created || []).length, committed: s.committed === true, packageManager: packageManagerByRepo[s.target.path] || null, contractSync: s.contractSync === true, gateCheck: scaffoldGateCheck(s) })))}
CI: ${JSON.stringify(ciResults)}
Backlog: ${JSON.stringify(backlog)}
Slice: ${JSON.stringify(sliceBuilt.map((b) => ({ repo: b.repo, summary: b.summary })))} (complete=${sliceComplete})
Gates: ${JSON.stringify(gates.allGates)}
Acceptance (validated resolved=${acceptanceResolved}): ${JSON.stringify(acceptance)}
Handoff: ${JSON.stringify(handoff)}`,
  { phase: 'Report', ...MODELS.report }
)

return {
  idea,
  greenfield: true,
  stacks: targets.map((t) => ({ role: t.role, stack: t.stack, path: t.path })),
  repoLayout: architecture.repoLayout,
  firstSlice: architecture.firstSlice.title,
  scaffolded,
  sliceComplete,
  gatesPassed: gates ? gates.allPassed : false,
  acceptanceResolved,
  architecturePlanSound: archSound,
  architectureImplemented,
  architectureSound: archSound && architectureImplemented,
  handoffDocs: handoff ? handoff.files || [] : [],
  ciConfigured,
  backlog: backlog ? { path: backlog.path, appended: backlog.appended || [] } : null,
  recommendation,
  stackOverlay: { ...stackOverlay, untrusted: untrustedManifests },
  next: trustNext || null,
  report,
}
